CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,global_admin BOOLEAN NOT NULL DEFAULT FALSE,mfa_secret TEXT NULL,mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE,mfa_counter BIGINT NOT NULL DEFAULT -1,disabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,base_url VARCHAR(2048) NOT NULL,key_cipher TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS grants (user_id BIGINT UNSIGNED NOT NULL,site_id BIGINT UNSIGNED NOT NULL,role ENUM('editor','siteadmin') NOT NULL,PRIMARY KEY(user_id,site_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,csrf CHAR(64) CHARACTER SET ascii NOT NULL,mfa_verified BOOLEAN NOT NULL DEFAULT FALSE,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(expires_at));
CREATE TABLE IF NOT EXISTS invitations (token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,email VARCHAR(254) NOT NULL,global_admin BOOLEAN NOT NULL DEFAULT FALSE,site_id BIGINT UNSIGNED NULL,role ENUM('editor','siteadmin') NULL,expires_at DATETIME(3) NOT NULL,used_at DATETIME(3) NULL,FOREIGN KEY(site_id) REFERENCES sites(id));
CREATE TABLE IF NOT EXISTS recovery (token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME(3) NOT NULL,used_at DATETIME(3) NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS backup_codes (user_id BIGINT UNSIGNED NOT NULL,code_hash CHAR(64) CHARACTER SET ascii NOT NULL,PRIMARY KEY(user_id,code_hash),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS login_attempts (subject_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,failures INT UNSIGNED NOT NULL DEFAULT 0,window_start DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,site_id BIGINT UNSIGNED NULL,event VARCHAR(80) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
